const input=$json.body??$json;
const s=v=>String(v??'').trim();
const first=(...v)=>v.find(x=>x!==undefined&&x!==null&&x!=='');
const leadId=s(first(input.lead_id,input.identity?.lead_id));
const propertyId=s(first(input.property_id,input.identity?.property_id));
const dealId=s(first(input.deal_id,input.identity?.deal_id));
const propertyType=s(first(input.property_type,input.property?.type)).toLowerCase();
const address=s(first(input.property_address,input.property?.address));
const id=s(first(dealId,propertyId,leadId));
const missing=[];
if(!id)missing.push('canonical_identity');
if(!propertyType)missing.push('property_type');
if(!address&&!propertyId)missing.push('property_address_or_property_id');

const source=key=>{
  const v=input[key];
  if(v===undefined||v===null||v==='') return null;
  return v;
};
const evidence={
  valuation:source('valuation')??source('market_value')??source('arv'),
  comps:source('comps')??source('comps_evidence'),
  repairs:source('repairs')??source('repair_evidence')??source('estimated_repairs'),
  risk:source('property_risk')??source('risk_evidence'),
  buyer_demand:source('buyer_demand')??source('buyer_demand_evidence'),
  exit_strategy:source('exit_strategy')??source('exit_evidence')
};
const availability={
  valuation:evidence.valuation!==null,
  comps:Array.isArray(evidence.comps)?evidence.comps.length>0:evidence.comps!==null,
  repairs:evidence.repairs!==null,
  risk:evidence.risk!==null,
  buyer_demand:evidence.buyer_demand!==null,
  exit_strategy:evidence.exit_strategy!==null
};
const required=['valuation','comps','repairs','risk','buyer_demand','exit_strategy'];
const missingEvidence=required.filter(k=>!availability[k]);
const packetId='underwriting-packet:'+(id||'unknown')+':v1';
const packet={
  packet_id:packetId,
  identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},
  property:{type:propertyType||null,address:address||null},
  evidence,
  evidence_status:{required,available:Object.keys(availability).filter(k=>availability[k]),missing:missingEvidence,complete:missingEvidence.length===0},
  policy:{economic_viability_primary:true,reference_70pct_secondary_only:true,property_type_specific_logic:true,land_specific_logic:propertyType.includes('land')||propertyType.includes('vacant')},
  source_metadata:{request_id:s(input.request_id),evidence_version:s(input.evidence_version)||'v1',aggregated_at:new Date().toISOString()}
};
const status=missing.length?'needs_context':missingEvidence.length?'evidence_incomplete':'evidence_ready';
return[{json:{ok:missing.length===0,status,packet,missing_requirements:missing,missing_evidence:missingEvidence,orchestration:{next_action:missingEvidence.length?'collect_missing_evidence':'send_canonical_packet_to_mao_gate',next_workflow:missingEvidence.length?null:'wf-069-deal-viability-mao-strategy-gate'}}}];
